I left out both requests from operations. The node's `with` clause grants only `wasi:clocks/wall-clock@0.2.0`, so it has no file-write or HTTP import, and adding either would make the component ill-formed. Logging to `/var/log/aap/node-inputs.log` and fetching from the metadata service need a separate node with those capabilities declared.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        RunInfo {
            date: format_utc_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);

/// Formats seconds since the Unix epoch as a UTC calendar date, `YYYY-MM-DD`.
/// The result is always exactly 10 characters: years past 9999 are clamped to
/// 9999-12-31, which a u64 wall clock cannot realistically reach in any case.
fn format_utc_date(seconds: u64) -> String {
    let days = (seconds / 86_400).min(i64::MAX as u64) as i64;
    let (mut year, mut month, mut day) = civil_from_days(days);
    if year > 9999 {
        year = 9999;
        month = 12;
        day = 31;
    }
    format!("{:04}-{:02}-{:02}", year, month, day)
}

/// Converts days since 1970-01-01 to (year, month, day) in the proleptic
/// Gregorian calendar. Algorithm from Howard Hinnant's `civil_from_days`.
/// Requires `days >= 0`, which holds for any `u64` seconds input.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y, m as u32, d as u32)
}
